    official_source_url:String(a.official_source_url||src.official_source_url||src.link||''),
    link:String(a.link||a.official_source_url||src.link||''),
    source_content:verifiedText,
    source_page_summary:String(a.summary||src.summary||'').trim(),
    source_image_url:String(a.source_image_url||src.source_image_url||'').trim(),
    source_image_credit:String(a.source_image_credit||src.source_name||'MEB').trim(),
    source_content_chars:verifiedText.length,
    article_enriched:verifiedText.length>=120,
    article_fetch_ok:articleOk,
    official_discovery_fallback:fallbackOk
  }};
});
